TP.register({id:"lp10-gtk",lp:10,grade:"TK",mode:"curriculum",checks:9,nextGrade:"Kindergarten",build(E){const F=E.F;const X={cake:"cake",balloon:"balloons",flag:"p_flag",horn:"megaphone",star:"star",ball:"soccerBall",book:"books",pencil:"pencil",palette:"palette",tree:"tree",leaf:"leaf",flower:"purpleFlower",sunflower:"sunflower",butterfly:"butterfly",bird:"bluebird",sun:"sun",rainbow:"rainbow",hat:"topHat",box:"box",bus:"bus",map:"map",phone:"phone",run:"run",swim:"swim",q:"question"};const COL={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",purple:"#8E5BC9"};const INK="#6B4A3C";const SKY="#D9EEF7",GRASS="#CBE8B0",GRASS_LN="#A0CC84",GRASS2="#AFD892",GRASS2_LN="#8CBA70",CREAM="#FBF1E4",TABLE="#D9A066",TABLE_D="#C08A5E",POLE="#B08968",PINK="#F4899E",GOLDL="#FBD873",SKYB="#9FD6F0",MINT="#B8E3A8",LILAC="#C9A6EC";const PARTY=[PINK,GOLDL,SKYB,MINT,LILAC];const LABEL="#3E2C22";const r1=v=>Math.round(v*10)/10;const svg=(w,h,body,alt,dw)=>`<svg viewBox="0 0 ${w} ${h}" width="${dw||w}" role="img" aria-label="${alt||"Picture"}">${body}</svg>`;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const at=(x,y,k,inner)=>`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})">${inner}</g>`;const frame=(w,h,fill)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${fill||"var(--surface)"}" stroke="var(--line)" stroke-width="4"/>`;const col=(...a)=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${a.join("")}</div>`;const tag=(x,y,t)=>`<circle cx="${x}" cy="${y}" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="${x}" y="${y+1}" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;function candleArt(c){return`<image href="data:image/webp;base64,${window.TP_CANDLE}" x="-9.3" y="-33" width="18.6" height="62"/>`}function candlePic(x,y,s,c){const k=s/26;return`<g transform="translate(${r1(x)} ${r1(y+2*k)}) scale(${r1(k)})">${candleArt(c)}</g>`}function candleTall(x,base,h,c){const k=h/60;return`<g transform="translate(${r1(x)} ${r1(base-28*k)}) scale(${r1(k)})">${candleArt(c)}</g>`}function balloonPic(x,y,s,c,noString){const k=s/44,c0=c||PINK;return`<g transform="translate(${r1(x)} ${r1(y)}) scale(${r1(k)})">`+(noString?"":`<path d="M0 26 C7 31 -7 35 0 40 C6 44 1 46 4 48" fill="none" stroke="#8A7A6A" stroke-width="2.6" stroke-linecap="round"/>`)+`<ellipse cx="0" cy="-2" rx="22" ry="21" fill="${c0}" stroke="${INK}" stroke-width="2.8"/><path d="M-7 15 H7 L0 28 Z" fill="${c0}" stroke="${INK}" stroke-width="2.8" stroke-linejoin="round"/><ellipse cx="0" cy="-2" rx="22" ry="21" fill="${c0}" stroke="none"/><path d="M-7 15 H7 L0 28 Z" fill="${c0}" stroke="none"/>`+at(0,-3,.5,K_FACE(0,0,12,4))+`</g>`}function bunting(x1,y1,x2,y2,n,drop){n=n||7;drop=drop==null?20:drop;const mx=(x1+x2)/2,my=(y1+y2)/2+drop*2;const atT=t=>[(1-t)*(1-t)*x1+2*t*(1-t)*mx+t*t*x2,(1-t)*(1-t)*y1+2*t*(1-t)*my+t*t*y2];let f="";for(let k=0;k<n;k++){const p=atT((k+.5)/n);f+=`<path d="M${r1(p[0]-9)} ${r1(p[1])} h18 l-9 19 Z" fill="${PARTY[k%5]}" stroke="${INK}" stroke-width="2.4" stroke-linejoin="round"/>`}return`<path d="M${x1} ${y1} Q${mx} ${my} ${x2} ${y2}" fill="none" stroke="${INK}" stroke-width="3.2" stroke-linecap="round"/>${f}`}const actPic=(x,y,n,s)=>{const d=window.TP_ACT[n],h=s*1.2,w=Math.min(h*d[1]/d[2],s*1.45);const hh=w*d[2]/d[1];return`<image href="data:image/webp;base64,${d[0]}" x="${x-w/2}" y="${y-hh/2}" width="${w}" height="${hh}"/>`};const put=(x,y,e,s)=>typeof e==="string"&&e.slice(0,4)==="ACT:"?actPic(x,y,e.slice(4),s):e==="CAND"?candlePic(x,y,s*.52):e==="BALL_P"?balloonPic(x,y,s,PINK,true):e==="BALL_U"?balloonPic(x,y,s,SKYB,true):em(x,y,e,s);function skyPanel(w,h){let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;b+=`<g fill="#FFFDF6" opacity=".85"><ellipse cx="${w*.72}" cy="58" rx="54" ry="22"/><ellipse cx="${w*.77}" cy="46" rx="36" ry="18"/><ellipse cx="${w*.66}" cy="48" rx="28" ry="16"/></g>`;return b}const grassBand=(w,top,bot)=>`<path d="M8 ${top} Q${w*.3} ${top-10} ${w*.6} ${top+4} T${w-8} ${top-2} V${bot} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-10} ${w*.6} ${top+4} T${w-8} ${top-2}" fill="none" stroke="${GRASS_LN}" stroke-width="3.4" stroke-linecap="round"/>`;const grassBand2=(w,top,bot)=>`<path d="M8 ${top} Q${w*.34} ${top-9} ${w*.64} ${top+5} T${w-8} ${top} V${bot} H8 Z" fill="${GRASS2}"/><path d="M8 ${top} Q${w*.34} ${top-9} ${w*.64} ${top+5} T${w-8} ${top}" fill="none" stroke="${GRASS2_LN}" stroke-width="3.2" stroke-linecap="round"/>`;const tableRun=(x0,x1,y)=>`<rect x="${x0}" y="${y}" width="${x1-x0}" height="16" rx="8" fill="${TABLE}" stroke="${INK}" stroke-width="3"/><path d="M${x0+22} ${y+16} v34 M${x1-22} ${y+16} v34" fill="none" stroke="${TABLE_D}" stroke-width="7" stroke-linecap="round"/>`;const sceneWord=(x,y,t)=>`<text x="${x}" y="${y}" font-size="26" font-weight="700" text-anchor="middle" fill="${LABEL}">${t}</text>`;function cards(list,o){o=o||{};const c=o.cell||190,s=o.size||110,gap=16,extra=o.num?42:0,w=list.length*(c+gap)-gap+6,h=c+extra+6;let b="";list.forEach((e,i)=>{const x=3+i*(c+gap);b+=`<rect x="${x}" y="3" width="${c}" height="${c}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`+put(x+c/2,3+c/2,e,s);if(o.num)b+=`<text x="${x+c/2}" y="${c+34}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,o.alt||"Picture cards")}function countPanel(groups,alt){const w=940,lh=88;let y=12,b="";groups.forEach((g,gi)=>{const e=g[0],n=g[1],per=g[2],cell=g[3],size=g[4],h=Math.ceil(n/per)*lh;if(gi)b+=`<path d="M22 ${y} H${w-22}" stroke="var(--line)" stroke-width="3"/>`;b+=tag(48,y+8+h/2,gi+1);for(let i=0;i<n;i++)b+=put(96+i%per*cell+cell/2,y+8+Math.floor(i/per)*lh+lh/2,e,size);y+=h+16});return svg(w,y+4,frame(w,y+4)+b,alt)}function cmpPanel(t,eA,nA,cellA,eB,nB,cellB,alt){const w=880,h=182;let b=frame(w,h)+tag(42,42,t);for(let i=0;i<nA;i++)b+=put(90+i*cellA+cellA/2,52,eA,56);for(let i=0;i<nB;i++)b+=put(90+i*cellB+cellB/2,132,eB,56);return svg(w,h,b,alt,800)}function scatterBox(e,n,seed,alt){const W=400,H=280;let x=seed,tries=0,gap=78;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};const pts=[];while(pts.length<n){const p=[56+rnd()*(W-112),54+rnd()*(H-108)];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>5e3){tries=0;gap-=4}}let b=frame(W,H);pts.forEach(p=>{b+=put(Math.round(p[0]),Math.round(p[1]),e,52)});return svg(W,H,b,alt,380)}const TRAY=[["p","b"],["u","s"],["u","b"],["p","s"],["u","s"],["p","b"],["p","s"],["u","b"]];function trayFig(){return svg(900,568,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="568"/>`,"A tray of eight balloons, four pink and four blue, some big and some small",620)}function pileFig(){return svg(720,527,`<image href="data:image/webp;base64," x="0" y="0" width="720" height="527"/>`,"A pile of objects mixed together: three stars, three flags, and two balls",470)}const CANDLES=[["A",150],["B",80],["C",110],["D",60],["E",95]];function candleRowFig(){return svg(1000,509,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="509"/>`,"Five candles standing in a row on the same cake board. They are different heights and are labeled A, B, C, D and E.",820)}const RIBBONS=[["1",300],["2",180],["3",440],["4",240]];function ribbonFig(){return svg(1000,508,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="508"/>`,"Four ribbons lying one above the other. They are different lengths and all start at the same dotted line on the left. They are labeled 1, 2, 3 and 4.",600)}function shapeFig(){return svg(1000,563,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="563"/>`,"The show yard with four shapes: a purple triangle party hat, a blue square gift box, a long green rectangle banner, and a yellow circle balloon")}function showScene(){return svg(1000,563,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="563"/>`,"The class show in the school yard: a girl walking past a paint table with an easel, a book table, and a garden bed with sunflowers, under a bunting string and a banner that says Our Class Show")}function heliumScene(){return svg(1000,667,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="667"/>`,"Pictures about balloons: a boy blowing up a pink balloon, a pink air balloon dropping to the floor, a purple tank with a green balloon, a glass of water with a bubble rising, and a green balloon floating up")}function yardScene(){return svg(1100,562,`<image href="data:image/webp;base64," x="0" y="0" width="1100" height="562"/>`,"A backyard on show day. A cake with candles sits on a purple table on the left. A smiling tree stands in the middle with a soccer ball at its trunk. A bird flies above the table. A pink flag on a pole stands on the right. A small yellow bus is far away on a hill behind.",900)}function boxFig(){const w=460,h=300;let b=frame(w,h);b+=`<image href="data:image/webp;base64," x="129" y="80" width="202" height="190"/>`;b+=em(230,40,X.q,56)+em(76,92,X.q,38)+em(382,92,X.q,38);return svg(w,h,b,"A gift box with a pink bow and a happy face, with question marks around it.")}function phoneFig(){const w=460,h=290;let b=frame(w,h);b+=`<image href="data:image/webp;base64,${window.TP_PHONE}" x="148" y="20" width="163" height="250"/>`;return svg(w,h,b,"A purple phone with a smiling face. Yellow lines beside it show that it is ringing.")}function ratherFig(){return`<div class="figure" style="align-items:center"><div style="text-align:center"><svg viewBox="0 0 320 292" width="320" role="img" aria-label="An art wall with six crayon drawings clipped up: a rainbow, a sun, a flower, a tree, a whale, and mountains. A paintbrush cup, a plant, and crayons sit on the shelf below." style="max-width:100%;height:auto"><image href="data:image/webp;base64," x="0" y="0" width="320" height="292"/></svg></div><span class="big">or</span><div style="text-align:center"><svg viewBox="0 0 300 282" width="300" role="img" aria-label="A garden bed with tomatoes, a sunflower, flowers, lettuce, and carrots growing in it. A watering can, a seed packet, and a trowel sit beside it." style="max-width:100%;height:auto"><image href="data:image/webp;base64," x="0" y="0" width="300" height="282"/></svg></div></div>`}function kid(x,y,r,fill){return`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="3"/>`+at(x,y,r/26,K_FACE(0,0,12,4.4))}function chartFig(){const w=880,h=240,r=30;let b=frame(w,h);b+=em(80,70,X.palette,84);b+=em(80,172,X.book,84);b+=`<path d="M150 20 V220" stroke="var(--line)" stroke-width="3"/>`;for(let i=0;i<7;i++)b+=TP_KIDPIC(196+i*92,70,72,[10,11,12,13,14,15,0][i]);for(let i=0;i<5;i++)b+=TP_KIDPIC(196+i*92,172,72,[3,18,19,22,27][i]);return svg(w,h,b,"A picture chart with two rows. The top row has a paint palette and seven faces. The bottom row has an open book and five faces.",840)}const TAG_LETTERS=["s","c","b","d","p","r"];function letterTagFig(){const cell=160,w=6*cell+40,h=250,IDX=[0,2,3,6,8,9],BP=window.TP_BALP||[];let b=frame(w,h);TAG_LETTERS.forEach((L,i)=>{const cx=20+i*cell+cell/2,p=BP[IDX[i]%Math.max(BP.length,1)];if(p){let ih=130,iw=ih*p[1]/p[2];if(iw>118){iw=118;ih=iw*p[2]/p[1]}b+=`<image href="data:image/webp;base64,${p[0]}" x="${r1(cx-iw/2)}" y="${r1(14)}" width="${r1(iw)}" height="${r1(ih)}"/>`}b+=`<rect x="${cx-34}" y="168" width="68" height="62" rx="14" fill="${CREAM}" stroke="${INK}" stroke-width="3.5"/>`;b+=`<text x="${cx}" y="201" font-size="54" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="#4A332A" font-family="var(--font-display)">${L}</text>`});return svg(w,h,b,"Six balloons in a row. A small tag sits under each balloon, and each tag has one lowercase letter on it.")}function patRow(num,list,size){const cell=96,w=list.length*cell+104,h=132;let b=frame(w,h);b+=tag(50,66,num);list.forEach((e,i)=>{b+=put(104+i*cell+cell/2,66,e,size||62)});b+=`<text x="${104+list.length*cell+28}" y="68" font-size="40" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--muted)">?</text>`;return svg(w+60,h,b,"A row of pictures that repeats, with a question mark at the end",Math.min(w+60,900))}function turnFig(){const st=`stroke="${INK}" stroke-width="4" stroke-linejoin="round"`;let b=frame(900,260);b+=`<rect x="276" y="76" width="112" height="112" rx="4" fill="${COL.blue}" ${st} transform="rotate(40 332 132)"/>`;b+=`<polygon points="130,76 190,196 70,196" fill="${COL.purple}" ${st} transform="rotate(180 130 136)"/>`;b+=`<rect x="498" y="112" width="196" height="46" fill="${COL.green}" ${st}/>`;b+=`<circle cx="806" cy="134" r="32" fill="${COL.yellow}" ${st}/>`;b+=`<text x="130" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">1</text>`;b+=`<text x="332" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">2</text>`;b+=`<text x="596" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">3</text>`;b+=`<text x="806" y="238" font-size="24" font-weight="700" text-anchor="middle" fill="var(--muted)">4</text>`;return svg(900,260,b,"Four shapes: an upside down purple triangle, a blue square tipped onto its corner, a long thin green rectangle, and a small yellow circle",860)}function pairCandleFig(){const w=700,h=250,base=192;let b=frame(w,h);b+=`<rect x="60" y="${base}" width="${w-120}" height="20" rx="10" fill="${CREAM}" stroke="${INK}" stroke-width="3.4"/>`;b+=candleTall(230,base,160,PINK);b+=candleTall(470,base,80,SKYB);b+=`<text x="230" y="${base+52}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">pink candle</text>`;b+=`<text x="470" y="${base+52}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">blue candle</text>`;return svg(w,h,b,"Two candles standing on the same cake board. The pink candle is tall and the blue candle is short.",660)}function mixedTrayFig(){const w=820,h=190;let b=frame(w,h);const order=[X.star,X.flag,X.star,X.ball,X.flag,X.star,X.star,X.flag,X.ball,X.star];order.forEach((e,i)=>{b+=put(52+i*76+38,96,e,58)});return svg(w,h,b,"A tray with ten things mixed together: stars, flags, and balls.",780)}const NIA="Nia was the last one ready on the last day of school. Her whole class had set up a show out in the yard, so that everyone could see what they made all year. Nia wanted to walk past every table before the music started. First she passed the paint table, where her big painting of a bird was pinned up. Next she passed the book table, where the class story book lay open. Then she came to the garden bed the class planted way back in the fall. <strong>(Stop here. Ask what Nia will do next.)</strong> Nia knelt down beside the garden bed and counted the sunflowers. There were three, and every one of them was taller than she was. Nia picked one leaf to keep in her pocket, and then she ran to the music.";const TOVA="Tova could not decide what to bring to the last day show. She had a painting of a boat, a tower she built out of blocks, and a song she made up herself. She carried the painting out to the table. Then she went back for the tower. Then she stood in the doorway and hummed her song very quietly. <strong>(Stop here. Ask what Tova will do next.)</strong> In the end Tova put the painting and the tower on the table, and when the music started she sang her song out loud for everybody. Her class clapped for a long time.";const HELIUM="A balloon is a stretchy bag that you fill up. When you blow a balloon up with air out of your own mouth, it falls back down to the floor when you let it go. Some balloons are filled with something different. It is called helium, and helium is lighter than the air all around us. A helium balloon pushes up through the air, the same way a bubble pushes up through a glass of water. That is why it pulls on the string instead of falling.";const LETTERS=["A","E","I","O","M","G","X","W","H","P","a","e","i","o","m","g"];const NUMS=["3","7","1","10","5","9","2","6","4","8"];const FIND12=["T","f","V","k","L","n","C","q","J","u","Z","y"];function findLetterFig(){const cell=152,per=6,w=per*cell+40,h=348;let b=frame(w,h);FIND12.forEach((L,i)=>{const cx=20+i%per*cell+cell/2,cy=26+Math.floor(i/per)*168;b+=`<rect x="${cx-56}" y="${cy}" width="112" height="128" rx="20" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/>`;b+=window.TP_LETTER_CARD(L,cx,cy)});return svg(w,h,b,"Twelve cards laid out in two rows of six. Each card has one printed letter on it.")}const BENCH_SAMPLE="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself.";const BENCH_DECK="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of any deck. A child sitting exactly at that goal still lands near 60 percent of whatever sample you show, and the suggested rating reads that as approaching. Set the rating yourself against those two counts.";const BENCH_STOP7="This stop and Find the Letter in stop 1 are scored under the same code, so their counts add together. The TK goal is a count of letters, about 15 to 20 of the 26 uppercase and about 12 to 16 of the 26 lowercase, and a child sitting right at that goal lands near 60 percent of any sample. Set the rating yourself against those two counts rather than taking the suggested one.";const BENCH_FULL="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. The two inventories are scored under one code, so a child right at goal lands near 33 of 52 and the suggested rating reads that as approaching. Hold the uppercase count and the lowercase count against the two numbers above and set the rating yourself.";const ALPHA_FULL=E.alphabet({std:["TK.ELA.FLS.2.4"],sounds:false}).map(p=>Object.assign({},p,{key:p.key.concat([BENCH_FULL])}));const STOPS=[{id:1,title:"Show Day Letters",short:"Letters",parts:[{title:"Find the Letter",std:["TK.ELA.FLS.2.4"],n:10,dur:90,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed form (12 cards, 6 uppercase and 6 lowercase)",fig:()=>F.row(findLetterFig()),key:["Say: Here are twelve letter cards from the show table. I will say a letter name. Point to the card with that letter.","Say: Point to the letter k. (top row, fourth card)","Say: Point to the letter L. (top row, fifth card)","Say: Point to the letter f. (top row, second card)","Say: Point to the letter y. (bottom row, sixth card)","Say: Point to the letter C. (bottom row, first card)","Say: Point to the letter u. (bottom row, fourth card)","Say: Point to the letter T. (top row, first card)","Say: Point to the letter q. (bottom row, second card)","Say: Point to the letter Z. (bottom row, fifth card)","Say: Point to the letter V. (top row, third card)","The top row reads T, f, V, k, L, n and the bottom row reads C, q, J, u, Z, y. Six cards are uppercase and six are lowercase, and two of the twelve are never asked for.","This is the direction the standard asks for: the child hears a name and finds the printed letter. Keep the uppercase and the lowercase results apart in your notes.","n and u are the same shape turned over, and q and y both hang below the line. Those two pairs are the ones to watch. If the child points to the wrong one of a pair, write down which one.","End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself."]},{title:"Name the Letter",std:["TK.ELA.FLS.2.4"],kind:"words",full:ALPHA_FULL,words:LETTERS,unit:"Letter",n:16,dur:85,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters (10 uppercase, 6 lowercase)",key:["Say: Every seat at the show has a letter card on it. Tell me the name of each letter. Click Next after each one.","Correct means the child says the letter name. If the child gives the sound instead, ask once: What is the name of this letter?","The first 10 are uppercase (A E I O M G X W H P). The last 6 are lowercase (a e i o m g).","Each of the last 6 is the small version of one of the first 6, so you hear the same name twice and can tell which shape the child knows. Write down the ones missed.","End of TK goal: about 15 to 20 uppercase and 12 to 16 lowercase letter names. This deck is a sample of 16, so write the uppercase and lowercase results separately in your notes.","These letters are not the ones used in the earlier games. If you have those record sheets, compare them.","If the child misses 4 in a row, stop and write down how many were tried.","Find the Letter at the top of this stop is the part this standard is written for. The standard asks the child to match a spoken name to its printed form, and naming a letter on sight is harder than that, so rate this standard on the Find the Letter count and keep this deck as the extra note.",BENCH_DECK]}]},{id:2,title:"Count the Party Table",short:"Count",parts:[{std:["TK.MATH.1.2"],n:6,dur:145,dir:"First count some small things from near you. Then count the pictures on the screen.",desc:"counting 10 or more real objects one by one where the teacher can see, then counting groups of 12, 14, 11, and 10 objects one by one on the screen",fig:()=>F.row(countPanel([["CAND",12,12,64,58],[X.balloon,14,7,108,58],[X.flag,11,6,110,58],[X.cake,10,5,120,60]],"Four groups to count: candles, balloons, flags, and cakes")),key:["Start with real things, before the screen. Say: Go and get ten small things you can hold, like spoons, blocks, socks or crayons, and set them on the table where I can see them. Then say: Move each one over to the side as you count it out loud. (One number word for each thing moved, no skips and no double counts. Moving each object is what makes the matching visible to you, so watch the hands as well as the numbers.)","Say: Push them back into a pile, add a few more, and count the whole lot again the same way. (Any number past ten. The goal is 10 or more with one number word for each object. If the count breaks down partway, write down the number it broke at.)","Those first two counts are the evidence for this standard, because they are the ones you can see for yourself. The screen rows below are still worth doing and they show whether a count holds together over bigger groups, but the child is pointing at a monitor you cannot see, so do not rate this standard on them alone and do not rate it on what an adult in the room reports.","Row 1. Say: Here are the candles waiting to go on the cake. Point to each candle on your screen and count out loud. (12 candles in one line) Look for one number word for each candle, with no skips and no double counts.","Row 2. Say: Now count the balloons. There are two lines of them. (14 balloons, in lines of 7 and 7)","Row 3. Say: Now count the flags. (11 flags, in lines of 6 and 5)","Row 4. Say: Now count the cakes. (10 cakes, in lines of 5 and 5)","Count an item correct only when the last number said matches the number of objects. On the screen rows, have the child say the numbers slowly enough that you can hear one number word for each picture, and watch the child's eyes move along the row. Where you cannot tell, leave the row out of the count rather than taking an adult's word for it.","Note where the count broke down: skipped a number, counted one twice, or lost track after 10."]}]},{id:3,title:"Yard Sounds",short:"Sounds",parts:[{title:"First Sound Check",std:["TK.ELA.FLS.2.1"],n:5,dur:60,dir:"Listen to your teacher. Say the first sound.",desc:"saying the first sound of a pictured word",fig:()=>F.row(cards([X.cake,X.sun,X.hat,X.map,X.pencil],{cell:160,size:96,alt:"Cake, sun, hat, map, pencil"})),key:["Model first: Ball. The first sound in ball is /b/. Now you try.","Point to the cake. Say: Cake. What is the first sound in cake? (/k/)","Point to the sun. Say: Sun. What is the first sound in sun? (/s/)","Point to the hat. Say: Hat. What is the first sound in hat? (/h/)","Point to the map. Say: Map. What is the first sound in map? (/m/)","Point to the pencil. Say: Pencil. What is the first sound in pencil? (/p/)","The answer is the sound, not the letter name. If the child says a letter name, ask: What sound do you hear first?"]},{title:"Rhyme Time",std:["TK.ELA.FLS.2.3"],n:4,dur:70,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.ball,X.tree,X.star,X.flag],{cell:170,size:100,alt:"Ball, tree, star, flag"})),key:["Model first: Cake, rake, lake. They rhyme. They sound the same at the end.","Point to the ball. Say: Tell me a word that rhymes with ball. (tall, fall, call, wall, mall, zall)","Point to the tree. Say: Tell me a word that rhymes with tree. (bee, key, sea, me, knee, zee)","Point to the star. Say: Tell me a word that rhymes with star. (car, far, jar, bar, gar)","Point to the flag. Say: Tell me a word that rhymes with flag. (bag, tag, wag, rag, zag)","Real words and silly words both count. A rhyme that is close but not perfect counts too."]},{title:"Put It Together",std:["TK.ELA.FLS.2.2"],n:4,dur:75,dir:"Listen to the slow, stretchy voice. Say the whole word.",desc:"blending syllables and sounds into a word with picture support",fig:()=>F.row(cards([X.balloon,X.pencil,X.cake,X.ball],{cell:170,size:104,alt:"A balloon, a pencil, a cake, a ball"})),key:["Say: I am going to talk very slowly today. Put the parts together and tell me the word. The four pictures are in the same order as the four words, so point to each one as you go.","Say with a pause between the parts: bal ... loon. (balloon, the first picture)","Say: pen ... cil. (pencil, the second picture)","Say the three sounds: /k/ ... /ay/ ... /k/. (cake)","Say the three sounds: /b/ ... /o/ ... /l/. (ball)","The first two are syllables. The last two are single sounds. Note which kind the child can blend."]}]},{id:4,title:"More Balloons or More Flags?",short:"More",parts:[{std:["TK.MATH.1.6"],n:4,dur:80,dir:"Look at the pictures. Answer out loud.",desc:"comparing two groups by counting (more, same, fewer)",fig:()=>col(cmpPanel(1,X.balloon,9,86,X.flag,6,86,"A row of nine balloons above a row of six flags"),cmpPanel(2,X.cake,5,90,X.star,5,90,"A row of five cakes above a row of five stars"),cmpPanel(3,X.tree,3,300,X.ball,8,86,"A row of three trees spread far apart above a row of eight balls packed close together"),cmpPanel(4,X.balloon,7,110,X.star,8,86,"A row of seven balloons spread apart above a row of eight stars")),key:["Box 1. Say: Are there more balloons or more flags? How do you know? (More balloons. 9 balloons and 6 flags.)","Box 2. Say: Are there more cakes, more stars, or the same number of each? (The same. 5 cakes and 5 stars.)","Box 3. Say: Which group has fewer, the trees or the balls? (Fewer trees. 3 trees and 8 balls. The trees are spread far apart and the balls are packed close together, so the tree row reaches further across the box even though there are only 3 of them.)","Box 4. Say: Which group has fewer, the balloons or the stars? (Fewer balloons. 7 balloons and 8 stars. The balloons are spread out, so their row reaches a little further.)","Look for counting, not guessing from how far a row reaches. Listen for the words more, same, fewer, or less.","If the child guesses from the length of the row in box 3 or box 4, say: Let's count them together, and note that the answer needed help."]}]},{id:5,title:"Nia Walks the Show",short:"Nia",parts:[{std:["TK.ELA.R.3.2"],n:4,dur:120,read:NIA,dir:"Listen to the story. Then answer out loud.",desc:"questions about the character, the order of three events, and what happens next in a story read aloud",html:()=>`<p class="big" style="text-align:center;margin:0 0 6px">Nia Walks the Show</p>`,fig:()=>F.row(showScene()),key:["If picture supports are on, point to the picture before you read. Say: This is a school yard on the last day of the year. The little flags on the string are called bunting. A garden bed is the long box of soil where the class planted things. The girl walking in from the left is Nia. The picture shows the three places she walks past, in the same order as the story.","Read the story out loud. Stop at the bold note, right after Nia comes to the garden bed.","Ask at the stopping place: What do you think Nia will do next? (Any guess that fits the story, like look at the flowers, count them, pick one, or run to the music.) Then read the rest.","Ask: Who is this story about? What did she want to do before the music started? (Nia. Walk past every table.)","Ask: Nia passed three things. What did she pass first? Next? Last? (First the paint table, next the book table, last the garden bed.) Count it correct when all three are in the right order.","Ask: How many sunflowers did she count? What did she keep? (Three sunflowers. One leaf, in her pocket.)","If picture supports are on, the picture on the screen can help the child remember. The picture shows the paint table with the bird painting, the open book on the book table, and the garden bed, in the same order as the story. The picture shows two big sunflowers, but the story says three, so ask the child to answer from the story and not from the picture."]}]},{id:6,title:"Show Shapes",short:"Shapes",parts:[{std:["TK.MATH.4.1"],n:6,dur:75,dir:"Look at the shapes. Answer out loud. Then draw a shape on your paper.",desc:"naming, describing, and drawing circles, squares, rectangles, and triangles",fig:()=>F.row(shapeFig()),key:["Say: Here is the show yard, drawn with shapes. What shape is the purple party hat? (triangle)","Say: What shape is the blue gift box? (square)","Say: What shape is the long green banner? (rectangle)","Say: What shape is the yellow balloon? (circle)","Say: Tell me about the green banner. How many sides does it have? How many corners? (4 sides and 4 corners. Words like straight, flat, long and short are a plus.)","Say: Draw a rectangle on your paper. Hold it up. (A closed shape with 4 straight sides and 4 corners, longer one way than the other. It does not need to be neat or even.)"]}]},{id:7,title:"Find the Letter",short:"Find It",parts:[{std:["TK.ELA.FLS.2.4"],n:5,dur:65,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed lowercase form",fig:()=>F.row(letterTagFig()),key:["Say: Every balloon at the show has a tag with a small letter on it. I will say a letter name. Point to the balloon with that letter.","Say: Point to the letter d. (fourth balloon from the left)","Say: Point to the letter s. (first balloon on the left)","Say: Point to the letter p. (fifth balloon from the left)","Say: Point to the letter b. (third balloon from the left)","Say: Point to the letter r. (last balloon on the right)","The tags read s, c, b, d, p, r from left to right. This is the other direction from the letter card deck: here the child hears the name and finds the printed letter.","b and d look alike, and so do b and p. If the child points to the wrong one of a pair, write down which one.",BENCH_STOP7]}]},{id:8,title:"Sort the Balloons",short:"Sort",parts:[{std:["TK.MATH.2.5"],n:6,dur:75,dir:"Look at the tray and the pile. Answer out loud.",desc:"sorting and classifying objects by color, by size, by two attributes at once, and making a rule",fig:()=>col(trayFig(),pileFig()),key:["Point to the tray. Say: Here are the balloons we are about to tie on the chairs. How many balloons are on the tray in all? (8)","Say: Sort them by color in your head. How many pink? How many blue? (4 pink and 4 blue)","Say: Now forget the color. Sort them by size. How many big? How many small? (4 big and 4 small)","Say: Now two things at once. Find the balloons that are pink AND big. How many? (2)","Say: Find the balloons that are blue AND small. How many? (2)","Point to the pile under the tray. Say: Put these into groups. How many groups did you make? Tell me your rule. (3 groups by what they are: 3 stars, 3 flags, 2 balls. Any rule the child can say and stick to counts, even one you did not expect.)","Sorting by two things at once is the hard part. If the child can sort by color and by size but not both at once, note that: one attribute is there and two is not yet."]}]},{id:9,title:"Count the Garden Bed",short:"Count 2",parts:[{std:["TK.MATH.1.2"],n:2,dur:80,dir:"Point to each one and count out loud.",desc:"counting groups of 15 and 13 objects one by one",fig:()=>F.row(countPanel([[X.sunflower,15,8,100,56],[X.butterfly,13,7,108,56]],"Two groups to count: sunflowers and butterflies")),key:["Row 1. Say: The class planted this bed way back in the fall, and now it is finished growing. Point to each sunflower and count out loud. (15 sunflowers, in lines of 8 and 7)","Row 2. Say: Now count the butterflies. (13 butterflies, in lines of 7 and 6)","Count an item correct only when the last number said matches the number of objects.","These two groups both carry over a line, so watch the moment the child reaches the end of the first line. Losing the count there is worth a note."]}]},{id:10,title:"Why a Balloon Pulls Up",short:"Balloons",parts:[{std:["TK.ELA.R.3.3"],n:3,dur:95,read:HELIUM,dir:"Listen to your teacher read about balloons. Then answer out loud.",desc:"making an inference, making a connection, and asking a question about an informational text read aloud",fig:()=>F.row(heliumScene()),key:["If picture supports are on, point to the picture first. Say: Here the boy blows up a pink balloon with air from his own mouth. When the pink balloon is let go, it drops down to the floor. This purple tank holds helium, and the green balloon filled with helium floats up. Over here is a glass of water with a bubble going up through it. Then read the facts out loud.","Ask: What do you think would happen if you let go of the string of the helium balloon outside? (It would go up and up into the sky and you could not get it back. The text does not say this part, so the child has to put two facts together.)","Ask: Have you ever held a balloon, or seen bubbles come up in a drink? Tell me about it. (Uses what the child already knows: held a balloon at a party, bubbles in soda, bubbles in the bath, a bubble wand. Any real answer from the child's own life counts.)","Say: What do you want to know about balloons? Ask me a question. You can start with What, Where, or Why. (Asks a real question about balloons, helium, air, or bubbles. Telling a fact instead of asking is not a question.)"]}]},{id:11,title:"Tallest Candle, Longest Ribbon",short:"Order",parts:[{std:["TK.MATH.3.2"],n:5,dur:80,dir:"Look at the candles and the ribbons. Answer out loud.",desc:"ordering five objects by height and four objects by length",fig:()=>col(candleRowFig(),ribbonFig()),key:["Point to the candles. Say: Five candles are standing on the cake board. Which candle is the tallest? (A)","Say: Which candle is the shortest? (D)","Say: Now put all five candles in order, from the shortest one to the tallest one. (D, B, E, C, A) Count it correct when all five are in the right order.","Point to the ribbons. Say: Which ribbon is the longest? Which one is the shortest? (Ribbon 3 is the longest. Ribbon 2 is the shortest.) All four start at the same dotted line, so the child can compare the far ends.","Say: Put all four ribbons in order, from the shortest one to the longest one. (2, 4, 1, 3) Count it correct when all four are in the right order.","Five in a row is harder than two. If the child can pick the tallest and the shortest but cannot order the middle three, write that down: the comparing is there and the ordering is not yet."]}]},{id:12,title:"Where in the Yard?",short:"Where",parts:[{std:["TK.MATH.4.5"],n:6,dur:70,dir:"Look at the yard. Answer out loud.",desc:"position words (on, under, next to, above, between, near and far)",fig:()=>F.row(yardScene()),key:["Say: Here is the whole yard on show day. Look at the long table. What is on the table? (the cake)","Say: What is under the tree? (the ball)","Say: What is next to the table? (the tree)","Say: Look up in the sky right above the table. What is up there? (the bird)","Say: What is between the table and the flag? (the tree, with the ball under it)","Say: Is the bus near the yard or far from the yard? (far. The bus is parked way off behind everything.)","Look for a position word in the answer, not only a pointing finger. If the child only points, ask: Can you tell me with words?"]}]},{id:13,title:"Number Cards",short:"Numbers",parts:[{std:["TK.MATH.1.5"],kind:"words",words:NUMS,unit:"Number",n:10,dur:60,dir:"Say the name of each number.",desc:"naming the numerals 1 to 10",key:["Say: The show has a number on every chair. What number is this? Click Next after each one.","Correct means the child says the number name. Write down the ones missed. Watch for 6 and 9 mixed up.","The card that reads 10 has two digits. Saying one and zero instead of ten is worth a note.","If the child counts up on fingers to find the name, note it. The goal is to know each numeral on sight."]}]},{id:14,title:"What Comes Next?",short:"Patterns",parts:[{std:["TK.MATH.2.6"],n:4,dur:70,dir:"Look at each row. Say what comes next.",desc:"extending repeating patterns and naming the part that repeats",fig:()=>col(patRow(1,[X.balloon,X.star,X.balloon,X.star,X.balloon,X.star,X.balloon]),patRow(2,[X.cake,X.cake,X.flag,X.flag,X.cake,X.cake,X.flag,X.flag]),patRow(3,["p_gift",X.leaf,X.ball,"p_gift",X.leaf,X.ball,"p_gift"],92)),key:["Row 1. Say: Balloon, star, balloon, star, balloon, star, balloon. What comes next? (a star)","Row 2. Say: Look at this row. What comes next? (a cake. The repeating part is cake, cake, flag, flag, and the row ends with the second flag.)","Row 3. Say: What comes next here? (a leaf. The repeating part is gift, leaf, ball, and the row ends with a gift.)","Go back to row 1. Say: What part keeps repeating over and over? (balloon, star)","Extra if there is time: clap and pat row 1 together (clap, pat, clap, pat). This shows the child can copy a pattern in a new way."]}]},{id:15,title:"The Class Chart",short:"Chart",parts:[{title:"Read the Chart",std:["TK.MATH.3.4"],n:4,dur:70,dir:"Look at the chart. Answer out loud. Then make marks on your paper.",desc:"reading, copying, and adding to a picture chart with two groups",fig:()=>F.row(chartFig()),key:["Say: The class picked what they liked best this year, painting or reading. Each face is one child. How many children picked painting? (7)","Say: Did more children pick painting or reading? (Painting. 7 is more than 5.)","Say: On your paper, make one mark for each child who picked reading. Hold it up. (5 marks, one for each face in the bottom row)","Say: One more child picks reading. What should we add to the chart? (One more face in the reading row, because each face stands for one child. That makes 6.)"]},{title:"One Face at a Time",std:["TK.MATH.1.2"],n:2,dur:60,dir:"Point to each face and count out loud.",desc:"counting the faces in each row of the chart one by one",fig:()=>F.row(chartFig()),key:["Say: Point to each face in the top row and count out loud. (7)","Say: Now point to each face in the bottom row and count out loud. (5)","The faces are all the same size and evenly spaced, so this is a clean check of one number word per face. Watch for a child who says the number of the row without touching each face."]}]},{id:16,title:"Cheer and Clap",short:"Cheer",parts:[{title:"One More Rhyme",std:["TK.ELA.FLS.2.3"],n:4,dur:75,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.hat,"book",X.sun,X.ball],{cell:170,size:100,alt:"Hat, one book, sun, ball"})),key:["Say: We are making up a cheer for the last day, and a cheer needs words that sound the same at the end.","Point to the hat. Say: Tell me a word that rhymes with hat. (cat, bat, mat, sat, pat, zat)","Point to the book. Say: Tell me a word that rhymes with book. (look, took, hook, cook, zook)","Point to the sun. Say: Tell me a word that rhymes with sun. (fun, run, bun, one, done, zun)","Point to the ball. Say: Tell me a word that rhymes with ball. (call, tall, wall, fall, small, zall)","Real words and silly words both count. These four are new words, so if a child who struggled earlier gets these, write that down."]},{title:"Say the Whole Word",std:["TK.ELA.FLS.2.2"],n:4,dur:75,dir:"Listen to the slow, stretchy voice. Say the whole word.",desc:"blending syllables and sounds into a word with picture support",fig:()=>F.row(cards([X.sunflower,X.butterfly,X.flag,X.star],{cell:170,size:104,alt:"A sunflower, a butterfly, a flag, a star"})),key:["Say: Here are four things from the show yard. Put the parts together and tell me the word. The four pictures are in the same order as the four words, so point to each one as you go.","Say with a pause between the parts: sun ... flower. (sunflower, the first picture)","Say: but ... ter ... fly. (butterfly, the second picture. Three parts this time.)","Say the four sounds: /f/ ... /l/ ... /a/ ... /g/. (flag)","Say the three sounds: /s/ ... /t/ ... /ar/. (star)","The first two are syllables and the last two are single sounds. Butterfly has three syllables, which is harder than two. Note which kind the child can blend."]}]},{id:17,title:"Label What You Made",short:"Write",parts:[{std:["TK.ELA.W.4.4"],n:3,label:"checks met",dur:85,dir:"Draw one thing you made or learned this year. Write letters to tell what it is. Hold it up.",desc:"writing letters to label a drawing",picSup:true,fig:()=>F.row(svg(540,362,`<image href="data:image/webp;base64," x="0" y="0" width="540" height="362"/>`,"Ten things children make or learn to do: a clay bowl with a paintbrush, a block castle, a stitched heart pillow with needle and thread, cookies on a plate, a plant in a pot, a rainbow and sun drawing with crayons, an open book with a light bulb, a bike and helmet, a guitar with music notes, and a chef hat with a mixing bowl.",820)),key:["If picture supports are on, point to the picture first. Say: Here are some things children make or learn to do, like a clay bowl, a block castle, cookies, a plant, a drawing, a book, riding a bike, and playing a guitar. Your idea can be anything. It does not have to be in the picture.","Say: Draw one thing you made this year, or one thing you learned to do. Then write a word or some letters to tell what it is. Hold it up and tell me what you wrote.","Look for: writing that is separate from the drawing (letters or marks that look like letters, not only a picture).","Look for: 2 or more letters you can recognize. They do not need to spell the word.","Look for: the child tells you what the writing says, like It says flower. This shows the letters stand for a word or an idea.","If the child writes only a name, that is a fine start. Ask: What does it say? Then ask for some letters about the drawn thing too."]}]},{id:18,title:"The Last Day Call",short:"Phone",parts:[{std:["TK.ELA.LS.1.5"],n:4,label:"checks met",dur:75,dir:"Your teacher is calling you. Ask questions until you know what to do.",desc:"asking questions to get missing information and to confirm understanding",fig:()=>F.row(phoneFig()),key:["Say: You are helping set up the show. I will call you on the phone, but part of my message will be missing. Ask me questions until you know what to do.","Message 1. Say in a phone voice: Hello! Please carry the box out to the table. Look for: asks a question about which box or which table (there are lots of boxes and three tables). If the child does not ask, prompt once: Do you know which one I mean? Then answer: The box of ribbons. The long table by the gate.","Message 2. Say: And bring enough chairs for the front row. Look for: asks a question about how many, like How many chairs? or How long is the row? Then answer: Bring six chairs.","Look for: a follow-up question that builds on your answer, like Do I need help carrying them? or What time does it start? Answer it in a few words.","Look for: says the plan back to you to make sure, like So the ribbon box and six chairs? If the child does not, ask: Can you tell me back what you will do? Count this check correct when the repeat is right and the child checks it with you.","Count a check only when the child asks or confirms. An answer with no question does not count here."]}]},{id:19,title:"The Box on the Table",short:"The Box",parts:[{title:"Mystery Box",std:["TK.ELA.LS.1.5"],n:3,label:"checks met",dur:70,dir:"Something the class made is in the box. Ask your teacher questions to find out what it is.",desc:"asking questions and follow-up questions to find out information",fig:()=>F.row(boxFig()),key:["Your secret: a crayon is in the box. Do not tell.","Say: One thing is packed in this box. Ask me questions to find out what it is. You can ask things like: Is it alive? What do you do with it?","Answer each question in a few words: It is not alive. It is small and it fits in your hand. It is made of wax. It has a paper wrapper around it. It comes in lots of colors. You use it on paper.","Look for: asks a real question to get information (not only a guess, like A ball!).","Look for: asks a follow-up question that builds on your answer (after You use it on paper, asks What color is it? or Is it a marker?).","Look for: checks the idea with a question at the end (Is it a crayon?). If the child is stuck after 4 or 5 questions, give one more clue."]},{title:"Name the Show Things",std:["TK.ELA.L.1.1"],n:6,dur:60,dir:"Look at each picture. Answer out loud.",desc:"naming objects, actions, and describing words from pictures",fig:()=>F.row(cards([X.balloon,X.cake,X.palette,"ACT:cook","ACT:soccer",X.butterfly],{cell:150,size:92,num:true,alt:"A balloon, a cupcake, a paint palette, a person cooking, a person kicking a soccer ball, a butterfly"})),key:["Picture 1. Say: What is this? (a balloon)","Picture 2. Say: What is this? (a cupcake, or a cake)","Picture 3. Say: You hold this flat tray while you paint, and the colors sit around the edge of it. What is it called? (a palette. This is a harder word. A paint tray also counts.)","Picture 4. Say: What is this person doing? (cooking, baking, or stirring)","Picture 5. Say: What is this person doing? (kicking a ball, or playing soccer)","Picture 6. Say: This is a butterfly. Tell me two words about what a butterfly is like. (Describing words such as little, pretty, soft, colorful, quiet, light, quick.)","Pictures 1 to 3 are naming words, 4 and 5 are action words, and 6 is describing words. Note which kind was hard."]},{title:"Art Wall or Garden",std:["TK.ELA.LS.1.7"],n:3,label:"checks met",dur:50,dir:"Pick one. Tell your teacher why.",desc:"sharing an opinion with a reason and details",fig:()=>ratherFig(),key:["Say: At the show you can stand by the art wall and show everybody your painting, or you can walk people through the class garden and show them what grew. Which one would you pick? Tell me why.","Look for: tells an opinion (picks one).","Look for: gives a reason that explains the pick. If there is no reason, ask once: Why?","Say: Tell me more about your turn at the show. What would you say to people? What would it feel like? Look for: 2 or more details in the description."]}]},{id:20,title:"Write the First Sound",short:"Sounds Down",parts:[{std:["TK.ELA.W.4.2"],n:3,dur:70,dir:"Look at each picture. Write the letter for the first sound on your paper.",desc:"writing a recognizable letter that stands for the first sound of a pictured word",fig:()=>F.row(cards([X.leaf,X.box,X.rainbow],{cell:180,size:108,num:true,alt:"A leaf, a box, and a rainbow"})),key:["Say: We are making signs for the show tables. I will name the picture, and you write the letter for the sound you hear at the start.","Picture 1. Say: Leaf. Leaf starts with /l/. Write the letter for /l/. (l or L)","Picture 2. Say: Box. Box starts with /b/. Write the letter for /b/. (b or B)","Picture 3. Say: Rainbow. Rainbow starts with /r/. Write the letter for /r/. (r or R)","Uppercase or lowercase both count. A letter written backwards still counts if you can tell which letter it is.","Count a letter correct only when it is the letter for that sound. Writing a different recognizable letter shows the child can form letters but not yet match one to a sound, so note it that way.","You say the sound out loud for the child here, so this is not a listening check. It is the writing check: does a letter the child forms stand for a sound."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Letter Names",std:["RF.K.1"],needs:["TK.ELA.FLS.2.4"],n:5,dir:"Say the name of each letter.",html:()=>F.cards(["Y","Q","N","f","q"],{size:"5rem",min:130}),key:["Y (the name is why)","Q (the name is cue, and the sound is /kw/)","N (watch for N and M mixed up)","f, the lowercase letter. Watch for f and t mixed up.","q, the lowercase letter. Watch for q mixed up with p or g.","TK asks for many letter names. Kindergarten asks for all 52 uppercase and lowercase letter names, so these are 5 that TK children miss most often. The name is the answer here, not the sound."]},2:{id:"L2",lv:true,title:"Level Up: How Many Altogether",std:["K.CC.B.4"],needs:["TK.MATH.1.2"],n:3,dir:"Count each group. Then tell your teacher how many there are.",html:()=>col(F.row(F.tenFrame(16)),F.row(scatterBox("CAND",9,31,"A mixed up group of candles"))),key:["Point to the ten frames at the top. Say: Count these dots and tell me how many there are in all. (16. Two full rows of five and then six more, with the second frame holding 6.)","Point to the mixed up candles underneath. Say: These are not lined up neatly. Count them and tell me how many. (9. Look for a plan, like touching each one on the screen so none is counted twice.)","Say: I will ask it a different way. How many candles were there altogether? (9, said straight back without recounting. Having to start the count over is worth a note.)","TK asks the child to count 10 or more objects one at a time, one number word per object. Kindergarten asks the child to answer the question how many, and to know that the last number said is the answer, for as many as 20 things in a line and as many as 10 scattered."]},4:{id:"L4",lv:true,title:"Level Up: Greater, Less, or Equal",std:["K.CC.C.6"],needs:["TK.MATH.1.6"],n:3,dir:"Look at the two boxes. Count, then answer out loud.",html:()=>col(F.row(scatterBox(X.balloon,9,13,"A group of balloons"),scatterBox(X.flag,7,29,"A group of flags")),F.row(scatterBox(X.cake,8,7,"A group of cakes"),scatterBox(X.star,8,41,"A group of stars"))),key:["Top pair. Ask: Which group is greater, the balloons or the flags? How do you know? (The balloons. 9 balloons and 7 flags. Look for counting, or for matching one flag to one balloon.)","Top pair again. Ask: So which group is less? (The flags. 7 is less than 9.)","Bottom pair. Ask: Are there more cakes, more stars, or are the two groups equal? (Equal. 8 cakes and 8 stars.)","TK asks for the words more, same, less or fewer. Kindergarten asks the child to say greater than, less than, or equal to, and to show it by counting or by matching the two groups one to one."]},5:{id:"L5",lv:true,title:"Level Up: Who, Where, What Happened",std:["RL.K.3"],needs:["TK.ELA.R.3.2"],n:3,dir:"Listen to the new story. Then answer out loud.",html:()=>F.row(cards([X.palette,X.box,"p_note"],{cell:170,size:110,alt:"A paint palette, a box, and a music note"})),key:["Read this story out loud, and point to each picture as it comes up: "+TOVA.replace(/<strong>.*?<\/strong> /,""),"Ask: Who is this story about? (Tova. Naming Tova is enough.)","Ask: Where does this story happen? (At school, at the last day show, carrying things out to the table. Any half of that counts.)","Ask: Tell me the big things that happened in this story, in order. (Tova could not decide what to bring, she carried the painting out, she went back for the tower, she hummed her song in the doorway, she sang it out loud and the class clapped.) Count it correct when 3 of the 5 are there in the right order.","TK asks the child to answer questions about details. Kindergarten asks the child to name the characters, the setting, and the major events of a story."]},6:{id:"L6",lv:true,title:"Level Up: Still the Same Shape",std:["K.G.A.2"],needs:["TK.MATH.4.1"],n:4,dir:"Look at the four shapes. Say the name of each one.",html:()=>F.row(turnFig()),key:["Say first: A shape keeps its name even when it is turned around or made bigger or smaller. Then ask: What shape is number 1? (a triangle. It is upside down, but it still has 3 straight sides and 3 corners.)","Ask: What shape is number 2? (a square. It is tipped onto its corner, but all 4 sides are the same length.)","Ask: What shape is number 3? (a rectangle. It is long and thin, but it still has 4 sides and 4 square corners.)","Ask: What shape is number 4? (a circle. It is small, but a circle is round all the way around whatever size it is.)","TK asks the child to identify and describe shapes. Kindergarten asks the child to name a shape correctly no matter which way it is turned or how big it is. Count a shape wrong only if the child names a different shape, not if the child adds words like tipped or long."]},11:{id:"L11",lv:true,title:"Level Up: Which One, and How Much",std:["K.MD.A.2"],needs:["TK.MATH.3.2"],n:3,dir:"Look at the two candles. Answer out loud.",html:()=>F.row(pairCandleFig()),key:["Ask: Which candle is taller, the pink one or the blue one? (the pink one)","Ask: How do you know? (Both candles stand on the same cake board, so the one whose top is higher is taller. Look for the child lining up the bottoms, not just pointing.)","Ask: Now say it the other way. Tell me about the blue candle in one sentence, using the word shorter. (The blue candle is shorter than the pink candle. The sentence has to name both candles and use shorter or less tall.)","TK asks the child to put four or five objects in order by length or height. Kindergarten asks the child to compare two objects directly on one measurable attribute and to say which one has more of it, in words like taller than or shorter than."]},15:{id:"L15",lv:true,title:"Level Up: Sort Them by How Many",std:["K.MD.B.3"],needs:["TK.MATH.3.4"],n:4,dir:"Look at the tray. Answer out loud.",html:()=>F.row(mixedTrayFig()),key:["Say first: Sort these into three groups: stars, flags, and balls. Then ask: How many stars? (5)","Ask: How many flags? (3)","Ask: How many balls? (2)","Ask: Now put the three groups in order, from the group with the fewest to the group with the most. (balls, flags, stars. That is 2, then 3, then 5.)","TK asks the child to show data with objects or marks, one for each thing. Kindergarten asks the child to classify into given categories, count each category, and then put the categories in order by how many are in each one."]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=15;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}" style="font-size:1.6rem">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){let c=`<div class="tf-wrap"><div class="tf">`;for(let k=0;k<10;k++)c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`;return c+`</div></div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear. The top row is a five frame.</p>`}function abcHtml(){return`<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">${"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(c=>`<span style="border:2px solid var(--line);border-radius:10px;padding:2px 10px;font-family:var(--font-display);font-weight:800;font-size:1.7rem">${c}${c.toLowerCase()}</span>`).join("")}</div>`}const TOOLS={np:{name:"Number path 1 to 15",std:["TK.MATH.1.2","TK.MATH.1.5","TK.MATH.1.6","TK.MATH.3.4","K.CC.B.4","K.CC.C.6","K.MD.B.3"],html:npHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{npOn[x.dataset.n]=!npOn[x.dataset.n];r()})},tf:{name:"Ten frame",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.4","K.CC.B.4","K.CC.C.6","K.MD.B.3"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},abc:{name:"Alphabet strip",std:["TK.ELA.W.4.4","TK.ELA.W.4.2","TK.ELA.FLS.2.4","RF.K.1"],html:abcHtml},talk:{name:"Talking starters",std:["TK.ELA.LS.1.7"],html:()=>`<ul class="starters"><li>I would pick ____ because ____.</li><li>I would tell people ____.</li><li>It would feel ____.</li></ul><p class="small">Say a starter out loud for the child to finish.</p>`}};const SUP_CAVEATS=[{t:"np",std:["TK.MATH.1.5"],msg:"The number path shows the numerals in order. If it was open during Number Cards, the child may have counted along the path to find a name. That is not the same as knowing the numeral on sight."},{t:"np",std:["TK.MATH.1.2","K.CC.B.4"],msg:"The number path helps the child keep the counting order. Note that the count was done with a visual."},{t:"np",std:["TK.MATH.1.6","K.CC.C.6"],msg:"The number path shows the numbers in order, so the child can see which one comes later. Note that the comparing was supported."},{t:"np",std:["TK.MATH.3.4","K.MD.B.3"],msg:"If the rows of the chart were counted along the number path, note that the totals came from a visual you supplied."},{t:"tf",std:["TK.MATH.1.6","K.CC.C.6"],msg:"If you matched the two groups on the ten frame, the child compared with a model you built. Note that the comparing was supported."},{t:"tf",std:["TK.MATH.2.5","TK.MATH.3.4"],msg:"If the ten frame was used to park each sorted group or each row of the chart, the child worked from a model you built. Note it."},{t:"abc",std:["TK.ELA.W.4.4"],msg:"With the alphabet strip the child can find a letter and copy it. That still fits the standard, but note whether the child chose the letters without being told which ones."},{t:"abc",std:["TK.ELA.FLS.2.4","RF.K.1"],msg:"The alphabet strip shows every letter in order. If it was open during the letter tasks, the child may have sung the alphabet to find a name. That is not the same as knowing the letter on sight."},{t:"talk",std:["TK.ELA.LS.1.7"],msg:"The talking starter supplies the word because. Count the reason check as supported."},{t:"abc",std:["TK.ELA.W.4.2"],msg:"The alphabet strip shows every letter. If it was open while the child wrote the first sounds, the child may have copied a shape rather than chosen it. Note whether you named the letter or only the sound."},{t:"scribe",std:["TK.ELA.W.4.4","TK.ELA.W.4.2"],msg:"If an adult wrote the letters or guided the child's hand, those letters do not count as the child's writing."},{t:"adult",msg:"If the adult at home gave a hint or the answer, do not count that item as correct on the child's own."},{t:"objects",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.2.5","TK.MATH.3.2","TK.MATH.2.6"],msg:"Counting, sorting, ordering or patterning real objects at home is a fine way to show this standard. Note what the child used and how many."},{t:"party",msg:"Bunting, a palette, helium and a garden bed are new words to some children. If you had to explain one of them, mark it here. Do not count an item wrong for not knowing a show-day word."}];function stopLogs(st){const math=st.std.some(c=>/^TK\.MATH|^K\./.test(c)),write=st.std.some(c=>/\.W\.4\./.test(c)),out=["repeat","adult","party"];if(math)out.push("objects");out.push("time");if(write)out.push("scribe");out.push("brk");return out}return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],stopLogs,logNames:{adult:"Adult at home helped",party:"Explained a show-day word"}}}});
